ALTER TABLE working_drafts ADD COLUMN desk_title_key text
GENERATED ALWAYS AS (vink_desk_key(CASE WHEN btrim(title, U&'\0009\000a\000b\000c\000d \0085\00a0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200a\2028\2029\202f\205f\3000') = '' THEN 'Chưa đặt tên' ELSE title END)) STORED;
COMMENT ON COLUMN working_drafts.desk_title_key IS
'Private display-title substring/sort key; not the public discovery key. PostgreSQL maintains it atomically with title.';
